-- Execute no SQL Editor do Supabase. Row Level Security isola os registros por usuário.
create table if not exists public.food_entries (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), entry_date date not null default current_date, meal text not null, name text not null, calories numeric not null default 0 check(calories>=0), protein_g numeric not null default 0 check(protein_g>=0), carbs_g numeric not null default 0 check(carbs_g>=0), fat_g numeric not null default 0 check(fat_g>=0), estimated boolean not null default false);
create table if not exists public.water_entries (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), entry_date date not null default current_date, milliliters integer not null check(milliliters>0));
create table if not exists public.exercise_entries (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), entry_date date not null default current_date, name text not null, minutes integer not null check(minutes>0), intensity text not null, notes text);
create table if not exists public.body_entries (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), entry_date date not null default current_date, weight_kg numeric not null check(weight_kg>0 and weight_kg<500), waist_cm numeric, hip_cm numeric, arm_cm numeric, thigh_cm numeric);
do $$ declare t text; begin foreach t in array array['food_entries','water_entries','exercise_entries','body_entries'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "Users manage own rows" on public.%I',t); execute format('create policy "Users manage own rows" on public.%I for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id)',t); end loop; end $$;
grant select,insert,update,delete on public.food_entries,public.water_entries,public.exercise_entries,public.body_entries to authenticated;
grant usage,select on all sequences in schema public to authenticated;
